/* Personal-brand experience: native scrolling, layered depth, editable stories. */
StudioModel.sections['Global reach']={key:'reach',variants:['Orbit','Quiet'],title:'Good work travels.',description:'Different places. Shared ambition.',items:[]};
const reachCountries=[['Denmark',56,10],['United Kingdom',54,-2],['France',47,2],['Germany',51,10],['United States',39,-98],['United Arab Emirates',24,54]];
const globeLocations=[...reachCountries,['Egypt',26,30],['Saudi Arabia',24,45],['Qatar',25,51],['Kuwait',29,48],['Bahrain',26,50],['Oman',21,57],['Jordan',31,36],['Lebanon',34,36],['Morocco',32,-6],['Tunisia',34,10],['Algeria',28,3],['Türkiye',39,35],['Turkey',39,35],['Netherlands',52,5],['Sweden',62,15],['Norway',62,10],['Finland',64,26],['Spain',40,-4],['Italy',42,12],['Portugal',39,-8],['Greece',39,23],['Switzerland',47,8],['Austria',48,14],['Poland',52,19],['Ireland',53,-8],['Belgium',51,4],['Canada',56,-106],['Mexico',23,-102],['Brazil',-14,-52],['Argentina',-34,-64],['Australia',-25,134],['New Zealand',-41,174],['India',21,79],['China',35,104],['Japan',36,138],['South Korea',36,128],['Singapore',1,104],['Indonesia',-2,118],['Malaysia',4,102],['Thailand',15,101],['South Africa',-30,25],['Kenya',0,38],['Nigeria',9,8]];
function normalizeExperience(){
  if(!state.personalBrand){const demo=state.profile.name==='Alex Morgan';state.personalBrand={enabled:true,clients:demo?24:0,projects:demo?38:0,years:demo?8:0,countries:demo?reachCountries.map(c=>c[0]):[],demo,eyebrow:'Independent in spirit. Collaborative by nature.',statement:'I turn a point of view into a brand people feel.',note:'The best work starts with a real conversation. I bring curiosity, clarity, and a little unexpected thinking to every one.',portrait:demo?'assets/alex-portrait.png':'',portraitAlt:demo?'Alex Morgan — fictional designer portrait':'',motion:'Full'};
    const a=state.sections.find(s=>s.type==='About'),w=state.sections.find(s=>s.type==='Selected Work');if(a&&w&&state.sections.indexOf(a)>state.sections.indexOf(w)){state.sections.splice(state.sections.indexOf(a),1);state.sections.splice(state.sections.indexOf(w),0,a)}
    if(!state.sections.some(s=>s.type==='Global reach'))state.sections.splice(a?state.sections.indexOf(a)+1:1,0,{id:'reach',type:'Global reach',visible:true});
  }
  StudioModel.normalize(state);
}
normalizeExperience();
function personalBrandSettings(){const b=state.personalBrand;modal('Your presence. Your story.',`<p class="muted">Shape the story people scroll through. Use your own achievements and places.</p><div class="form-grid" style="margin-top:24px">${field('Your name','profile.name',state.profile.name)}${field('Professional title','profile.title',state.profile.title)}${field('Opening line','brand.eyebrow',b.eyebrow)}${selectField('Scroll motion','brand.motion',b.motion,['Full','Subtle','Off'])}<div class="span2">${field('About statement','brand.statement',b.statement,'textarea')}${field('Personal note','brand.note',b.note,'textarea')}</div>${field('Clients worked with','brand.clients',b.clients,'number')}${field('Projects completed','brand.projects',b.projects,'number')}${field('Years of experience','brand.years',b.years,'number')}<div class="span2">${field('Countries · one per line','brand.countries',b.countries.join('\n'),'textarea')}</div><div class="span2">${field('Portrait description','brand.portraitAlt',b.portraitAlt)}</div></div><div class="row">${btn('Change portrait','choose-media:brand','','image')}${btn('Profile & links','profile-details','quiet')}</div><label class="check-row" style="margin-top:22px"><input type="checkbox" data-brand-demo ${b.demo?'checked':''}>These are illustrative demo figures</label><p class="help-tip">The country count follows your list automatically. Reduced-motion preferences are always respected.</p>`,btn('Done','close-dialog','primary'))}
const beforeBrandMedia=setMedia;
setMedia=function(url,name){if(mediaTarget==='brand'){mutate(()=>{state.personalBrand.portrait=url;state.personalBrand.portraitAlt=name;state.profile.photo=url;state.profile.photoAlt=name});closeModal();return}beforeBrandMedia(url,name)};
const beforeBrandUpdate=updateField;
updateField=function(id,value,rerender=true){if(id.startsWith('brand.')){const key=id.slice(6);mutate(()=>state.personalBrand[key]=key==='countries'?[...new Set(value.split('\n').map(s=>s.trim()).filter(Boolean))]:['clients','projects','years'].includes(key)?Math.max(0,Number(value)||0):value,rerender&&!$('#dialog').open);return}beforeBrandUpdate(id,value,rerender)};
const beforeBrandAction=handleExtraAction;
handleExtraAction=function(action,value){if(action==='preview-home'&&state.personalBrand.enabled){activePreviewProject=null;page='Home';render();requestAnimationFrame(()=>document.querySelector('[data-chapter=work]')?.scrollIntoView({block:'start'}));return}if(action==='brand-settings'){personalBrandSettings();return}if(action==='journey'){const pf=document.querySelector('.brand-experience');pf?.querySelector('[data-chapter="'+value+'"]')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches||state.personalBrand.motion==='Off'?'instant':'smooth',block:'start'});return}if(action==='toggle-experience'){mutate(()=>state.personalBrand.enabled=!state.personalBrand.enabled);return}beforeBrandAction(action,value)};
document.addEventListener('change',e=>{if(e.target.hasAttribute('data-brand-demo'))mutate(()=>state.personalBrand.demo=e.target.checked,false)});
document.addEventListener('input',e=>{if(e.target.dataset.field)requestAnimationFrame(initStoryMotion)});
function storyAttr(s,edit,key){return `data-chapter="${key}" ${edit?`data-section="${s.id}" tabindex="0" aria-label="Select ${esc(s.type)} section"`:''}`}
function storyHero(s,edit){const b=state.personalBrand,p=state.profile,photo=p.photo||b.portrait;return `<section class="story-hero" ${storyAttr(s,edit,'home')}><div class="hero-orbit" aria-hidden="true"><span></span><span></span><span></span></div><div class="story-intro"><span class="micro-label">${esc(p.title)}</span><span class="hero-location">${esc(p.location||'Available worldwide')}<br>Independent / ${new Date().getFullYear()}</span></div><div class="story-title"><span class="hello-line">${esc(b.eyebrow)}</span><h1><span>${esc(p.name.split(' ')[0]||'Your')}</span><i>${esc(p.name.split(' ').slice(1).join(' ')||'perspective.')}</i><span class="hero-star" aria-hidden="true">✳</span></h1></div><div class="portrait-scene"><div class="portrait-depth">${photo?`<img class="story-portrait" src="${esc(photo)}" alt="${esc(p.photoAlt||b.portraitAlt||p.name)}" fetchpriority="high">`:`<div class="story-portrait-empty">Your face.<br>Your story.</div>`}<div class="portrait-shade"></div></div><span class="portrait-caption">A person behind every idea.</span>${edit?btn('Change portrait','choose-media:brand','portrait-edit','image'):''}</div><div class="hero-signature"><span class="signature">${esc(p.name.split(' ')[0]||'You')}.</span><p>${esc(p.bio)}</p></div><div class="hero-bottomline"><button class="scroll-invitation" data-action="journey:about"><span class="round-arrow">↓</span><span>There’s a story here.<br><strong>Scroll to get to know me.</strong></span></button>${p.availability?'<span class="story-available"><b></b>Open for meaningful collaborations</span>':''}<span class="chapter-number">01 / 05</span></div></section>`}
function storyAbout(s,edit){const b=state.personalBrand;return `<section class="story-about" ${storyAttr(s,edit,'about')}><div class="chapter-head"><span class="micro-label">01 — A LITTLE ABOUT ME</span><span class="thin-cross">+</span></div><div class="story-about-grid"><span class="about-aside">Strategy in my head.<br>Craft in my hands.<br>People at the heart.</span><div><h2 class="reveal-statement">${b.statement.split(/\s+/).map(w=>`<span>${esc(w)} </span>`).join('')}</h2><div class="story-bio"><p>${esc(state.profile.bio)}</p><p>${esc(b.note)}</p></div>${edit?btn('Edit my story','brand-settings','story-text-link'):''}<div class="story-specialties">${state.profile.skills.map(s=>`<span>${esc(s)}</span>`).join('')}</div></div></div><div class="word-ribbon" aria-hidden="true"><div>Curiosity. <i>Clarity.</i> Character. <span>✳</span> Curiosity. <i>Clarity.</i> Character. <span>✳</span></div></div></section>`}
function storyReach(s,edit){const b=state.personalBrand;return `<section class="story-reach" ${storyAttr(s,edit,'reach')}><div class="chapter-head"><span class="micro-label">02 — CONNECTIONS, WITHOUT BORDERS</span><span class="thin-cross">+</span></div><div class="reach-grid"><div class="reach-copy"><h2>Good work<br><i>travels.</i></h2><p>${esc(s.content.description||'Different places. Shared ambition.')}</p><div class="reach-stat"><strong data-count="${b.countries.length}">${String(b.countries.length).padStart(2,'0')}</strong><span>countries.<br>And counting.</span></div><div class="country-list">${b.countries.map((n,i)=>`<span><small>${String(i+1).padStart(2,'0')}</small>${esc(n)}</span>`).join('')||'<span>Add the places your work has taken you.</span>'}</div>${edit?btn('Edit numbers & countries','brand-settings','story-text-link'):''}</div><div class="globe-scene"><canvas class="story-globe" aria-label="Rotating globe showing international collaboration" role="img"></canvas><div class="globe-orbit-label"><span>BASED IN ${esc(state.profile.location.split(',')[0]||'YOUR CITY').toUpperCase()}</span><span>CONNECTED EVERYWHERE ↗</span></div></div></div><div class="story-numbers">${[[b.clients,'Clients & collaborators'],[b.projects,'Projects brought to life'],[b.years,'Years of independent thinking']].map(([n,label])=>`<div><strong><span data-count="${n}">${n}</span><i>+</i></strong><span>${label}</span></div>`).join('')}</div>${b.demo?'<p class="demo-footnote">Illustrative figures & locations · fictional portfolio</p>':''}</section>`}
function storyWork(s,edit){const projects=state.projects.filter(p=>!['Hidden','Archived'].includes(p.status)&&p.featured);return `<section class="story-work" ${storyAttr(s,edit,'work')}><div class="chapter-head"><span class="micro-label">03 — SELECTED COLLABORATIONS</span><span>${String(projects.length).padStart(2,'0')} STORIES</span></div><h2>A few things<br>I’ve put my <i>heart into.</i></h2><div class="story-projects" style="--story-columns:${state.personalBrand.workColumns==='3'?3:2}">${projects.map((p,i)=>`<button class="story-project" style="--card-index:${i}" data-action="${edit?'project:':'preview-project:'}${p.id}"><div class="story-project-image"><img src="${esc(p.cover)}" alt="${esc(p.alt||p.title)}" loading="lazy"><span class="project-open">Explore the story ↗</span><span class="project-index">0${i+1}</span></div><div class="story-project-caption"><h3>${esc(p.title)}</h3><span>${esc(p.type)}<br>${esc(p.year)}</span><span class="project-circle">↗</span></div></button>`).join('')||`<div class="empty"><p>Your next chapter starts with a project.</p>${edit?btn('Add your first project','quick-add','primary'):''}</div>`}</div></section>`}
function storyContact(s,edit){const p=state.profile;return `<section class="story-contact" ${storyAttr(s,edit,'contact')}><div class="chapter-head"><span class="micro-label">04 — THE NEXT CHAPTER</span><span class="thin-cross">✳</span></div><p>Good things start with a conversation.</p><h2>Have a feeling<br>we’d <i>click?</i></h2>${p.email?`<a class="contact-orbit" href="mailto:${esc(p.email)}"><span>Say hello</span><span>↗</span></a>`:''}<div class="contact-bottom"><a href="mailto:${esc(p.email)}">${esc(p.email)}</a><div>${socialLinks()}</div><button data-action="journey:home">Back to the top ↑</button></div></section>`}
const classicPortfolio=portfolio;
portfolio=function(edit=false,mini=false){normalizeExperience();if(!state.personalBrand.enabled||page!=='Home')return classicPortfolio(edit,mini);const p=state.profile;return `<article class="portfolio brand-experience ${device} ${state.personalBrand.motion.toLowerCase()} ${edit?'is-editing':''}" data-motion="${state.personalBrand.motion}" style="--story-accent:${state.accent}"><nav class="story-nav"><button data-action="journey:home" class="story-monogram">${esc(p.name.split(' ').map(w=>w[0]).slice(0,2).join(''))}<span>®</span></button><div><button data-action="journey:about">The person</button><button data-action="journey:work">The work</button><button data-action="journey:contact">Let’s talk <span>↗</span></button></div><span class="story-nav-note">A PORTFOLIO WITH A POINT OF VIEW</span></nav>${state.sections.filter(s=>s.visible).map(s=>s.type==='Hero'?storyHero(s,edit):s.type==='About'?storyAbout(s,edit):s.type==='Global reach'?storyReach(s,edit):s.type==='Selected Work'?storyWork(s,edit):s.type==='Contact'?storyContact(s,edit):s.type==='Footer'?`<footer class="story-footer"><span>© ${new Date().getFullYear()} ${esc(p.name)}</span><span>Made with feeling. Made with Sitofolio.</span></footer>`:portfolioSection(s,edit)).join('')}</article>`};
const beforeBrandRight=editorRight;
editorRight=function(){const s=activeSection();if(state.personalBrand.enabled&&page==='Home'&&s&&['Hero','About','Global reach','Selected Work','Contact'].includes(s.type))return `<aside class="right-panel"><div class="prop-head"><h3>${esc(s.type)}</h3>${ib('more','section-options','Section actions')}</div><div class="panel-block"><span class="eyebrow">PERSONAL BRAND EXPERIENCE</span><div class="experience-mini"><span>${esc(state.profile.name.split(' ')[0]||'Your')}</span><i>${esc(state.profile.name.split(' ').slice(1).join(' ')||'story.')}</i><b>✳</b></div><h3 style="margin:20px 0 10px">A story, in motion.</h3><p class="help-tip">Portrait, personal story, global reach, and work. One continuous experience.</p>${btn('Edit my story & achievements','brand-settings','full','type')}${s.type==='Hero'?btn('Change portrait','choose-media:brand','quiet full','image'):''}${s.type==='Selected Work'?btn('Manage projects','go:projects','quiet full','grid'):''}${s.type==='Contact'?btn('Contact details & links','profile-details','quiet full'):''}</div><div class="panel-block">${selectField('Scroll motion','brand.motion',state.personalBrand.motion,['Full','Subtle','Off'])}<p class="help-tip">Full adds layered parallax, perspective, and a rotating globe. Subtle keeps gentle entrances. Off is static.</p></div><div class="panel-block">${btn('Experience the full page','go:preview','primary full','eye')}${btn('Global typography & colors','global','quiet full','settings')}</div></aside>`;return beforeBrandRight()};
const beforeBrandGlobal=globalProperties;
globalProperties=function(){return `<div class="panel-block"><span class="eyebrow">HOME EXPERIENCE</span>${btn(state.personalBrand.enabled?'Switch to classic sections':'Use personal-brand story','toggle-experience','full')}${btn('My story & achievements','brand-settings','quiet full')}</div>`+(state.personalBrand.enabled?`<div class="panel-block">${field('Accent color','accent',state.accent,'color')}${selectField('Scroll motion','brand.motion',state.personalBrand.motion,['Full','Subtle','Off'])}<p class="help-tip">Acumin and Instrument Serif. Warm ivory, ink, and your accent. A continuous composition built around your story.</p></div>`:beforeBrandGlobal())};
let stopStoryMotion=()=>{};
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>initStoryMotion());
const beforeBrandRender=render;
render=function(){stopStoryMotion();normalizeExperience();beforeBrandRender();document.body.classList.toggle('immersive-preview',view==='preview'&&!activePreviewProject&&page==='Home'&&state.personalBrand.enabled);if(view==='editor')$('.panel-foot')?.insertAdjacentHTML('afterbegin',`<button class="nav-row" data-action="brand-settings">${icon('globe')}My story & achievements</button>`);requestAnimationFrame(initStoryMotion)};
function initStoryMotion(){
  stopStoryMotion();const roots=[...document.querySelectorAll('.brand-experience')];if(!roots.length)return;
  const cleanup=[];const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let frame=0,active=true;
  for(const root of roots){
    const scroller=root.closest('.canvas-wrap')||root.closest('.preview-shell.with-publish .preview-canvas')||window;
    const motion=root.dataset.motion!=='Off'&&!reduced,full=motion&&root.dataset.motion==='Full';root.classList.toggle('motion-enabled',motion);
    const hero=root.querySelector('.story-hero'),portrait=root.querySelector('.portrait-scene'),title=root.querySelector('.story-title'),about=root.querySelector('.story-about'),words=[...root.querySelectorAll('.reveal-statement span')],ribbon=root.querySelector('.word-ribbon>div'),projects=[...root.querySelectorAll('.story-project')];
    const update=()=>{if(!active||!root.isConnected)return;const top=scroller===window?0:scroller.getBoundingClientRect().top, height=scroller===window?innerHeight:scroller.clientHeight;const hr=hero?.getBoundingClientRect(),ar=about?.getBoundingClientRect();if(full&&hr){const progress=Math.max(0,Math.min(1,(top-hr.top)/hr.height));portrait?.style.setProperty('--portrait-y',progress*100+'px');portrait?.style.setProperty('--portrait-rotate',(-5+progress*9)+'deg');title?.style.setProperty('transform',`translate3d(${-progress*45}px,${progress*70}px,0)`);}
      if(motion&&ar){const progress=Math.max(0,Math.min(1,(height*.87-(ar.top-top))/(height*.7)));words.forEach((w,i)=>w.style.opacity=progress>(i/words.length)?'1':'.24');if(ribbon)ribbon.style.transform=`translateX(${-progress*120}px)`}
      if(full&&!root.querySelector('.story-projects'))projects.forEach((card,i)=>{const next=projects[i+1];const d=next?Math.max(0,Math.min(1,(height*.65-(next.getBoundingClientRect().top-top))/(height*.6))):0;card.style.transform=`perspective(1400px) scale(${1-d*.075}) rotateX(${d*4}deg)`;card.style.filter=`brightness(${1-d*.25})`});
    };
    const schedule=()=>{if(!frame)frame=requestAnimationFrame(()=>{frame=0;update()})};scroller.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);cleanup.push(()=>{scroller.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule)});update();
    if(full&&portrait&&hero){const pointer=e=>{const r=hero.getBoundingClientRect();portrait.style.setProperty('--pointer-x',((e.clientX-r.left)/r.width-.5)*12+'deg')};const reset=()=>portrait.style.setProperty('--pointer-x','0deg');hero.addEventListener('pointermove',pointer);hero.addEventListener('pointerleave',reset);cleanup.push(()=>{hero.removeEventListener('pointermove',pointer);hero.removeEventListener('pointerleave',reset)})}
    const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}}),{threshold:.12,root:scroller===window?null:scroller});root.querySelectorAll('.reach-copy,.story-numbers>div,.story-work>h2,.story-contact>h2').forEach(el=>observer.observe(el));cleanup.push(()=>observer.disconnect());
    if(motion){const countFrames=new Set();const counter=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;counter.unobserve(entry.target);const node=entry.target,target=Number(node.dataset.count),start=performance.now();const tick=now=>{if(!active)return;const progress=Math.min(1,(now-start)/1100);node.textContent=Math.round(target*(1-Math.pow(1-progress,3)));if(progress<1){const id=requestAnimationFrame(time=>{countFrames.delete(id);tick(time)});countFrames.add(id)}};tick(start)}),{threshold:.6,root:scroller===window?null:scroller});root.querySelectorAll('[data-count]').forEach(el=>counter.observe(el));cleanup.push(()=>{counter.disconnect();countFrames.forEach(cancelAnimationFrame)})}
    const canvas=root.querySelector('.story-globe');if(canvas)cleanup.push(drawStoryGlobe(canvas,full));
  }
  stopStoryMotion=()=>{active=false;cancelAnimationFrame(frame);cleanup.forEach(fn=>fn())};
}
// Orthographic sphere with approximate continent silhouettes and geographic pins.
function drawStoryGlobe(canvas,animate){const ctx=canvas.getContext('2d');if(!ctx)return ()=>{};let running=true,raf=0,visible=false,angle=-.25;const countries=state.personalBrand.countries.map(n=>globeLocations.find(c=>c[0].toLowerCase()===n.toLowerCase())).filter(Boolean);
  const polygons=[[[ -168,70],[-140,72],[-125,60],[-110,55],[-60,52],[-54,35],[-82,24],[-98,16],[-118,32],[-130,50]], [[-81,12],[-48,0],[-35,-10],[-52,-30],[-69,-55],[-78,-25]], [[-15,36],[20,37],[50,10],[40,-20],[18,-35],[0,-5],[-17,15]], [[-10,36],[-9,60],[25,72],[70,70],[105,78],[170,60],[150,40],[120,20],[100,0],[80,8],[60,28],[35,30]], [[112,-12],[145,-10],[155,-28],[135,-40],[115,-30]], [[-52,60],[-20,65],[-30,83],[-55,80]]];
  const inside=(x,y,poly)=>{let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])yes=!yes}return yes};
  const dots=[];for(let lat=-70;lat<80;lat+=3)for(let lon=-180;lon<180;lon+=3.5)if(polygons.some(p=>inside(lon,lat,p)))dots.push([lat,lon]);
  function paint(){if(!running)return;const w=canvas.clientWidth||600,h=canvas.clientHeight||600,dpr=Math.min(devicePixelRatio,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const radius=Math.min(w,h)*.37,cx=w/2,cy=h/2;const project=(lat,lon)=>{const a=lat*Math.PI/180,b=lon*Math.PI/180+angle;return [cx+radius*Math.cos(a)*Math.sin(b),cy-radius*Math.sin(a),Math.cos(a)*Math.cos(b)]};
    const glow=ctx.createRadialGradient(cx-radius*.4,cy-radius*.4,0,cx,cy,radius*1.12);glow.addColorStop(0,'#38352f');glow.addColorStop(.8,'#181918');glow.addColorStop(1,'#101211');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(cx,cy,radius,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle='#e5daca19';ctx.lineWidth=.65;for(let lat=-60;lat<=60;lat+=20){ctx.beginPath();let begun=false;for(let lon=-180;lon<=180;lon+=2){const [x,y,z]=project(lat,lon);if(z>0){begun?ctx.lineTo(x,y):ctx.moveTo(x,y);begun=true}else begun=false}ctx.stroke()}for(let lon=-180;lon<180;lon+=25){ctx.beginPath();let begun=false;for(let lat=-88;lat<=88;lat+=2){const[x,y,z]=project(lat,lon);if(z>0){begun?ctx.lineTo(x,y):ctx.moveTo(x,y);begun=true}else begun=false}ctx.stroke()}
    dots.forEach(([lat,lon])=>{const[x,y,z]=project(lat,lon);if(z<0)return;ctx.fillStyle=`rgba(232,222,204,${.25+z*.6})`;ctx.beginPath();ctx.arc(x,y,1+z*.6,0,Math.PI*2);ctx.fill()});
    countries.forEach(([name,lat,lon])=>{const[x,y,z]=project(lat,lon);if(z<.12)return;ctx.strokeStyle='#ff5a3c88';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#ff5a3c';ctx.beginPath();ctx.arc(x,y,3,0,Math.PI*2);ctx.fill();if(name==='United States'||name==='United Arab Emirates'||name==='Denmark'){ctx.fillStyle='#f6f1e8';ctx.font='10px Arial';ctx.fillText(name.toUpperCase(),x+12,y-9)}});
    ctx.strokeStyle='#f6f1e821';ctx.beginPath();ctx.ellipse(cx,cy,radius*1.24,radius*.31,-.35,0,Math.PI*2);ctx.stroke();if(animate&&visible&&!document.hidden)angle+=.0013;if(animate&&visible)raf=requestAnimationFrame(paint);
  }
  const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;cancelAnimationFrame(raf);if(visible)paint()},{threshold:0});observer.observe(canvas);paint();return ()=>{running=false;cancelAnimationFrame(raf);observer.disconnect()};
}
render();
